"""Deliberately naive reference implementation of the published contract.

Everything is expanded to plain bytes and the replay is an explicit state
machine, so it is an independent check of the project's compressed code paths.
Only small inputs are used.
"""
import hashlib

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1


def fp(data):
    h = 0
    for value in data:
        h = (h * 257 + value + 1) & MASK
    return {'n': len(data), 'h': '%016x' % h}


def cat(items):
    out = b''
    for item in items:
        out += item
    return out


# ---------------------------------------------------------------- templates #
def evaluate(source, env):
    """Direct byte-program evaluator for generated expressions."""
    import ast
    import operator
    tree = ast.parse(source, mode='eval')

    def go(node):
        if isinstance(node, ast.Constant):
            v = node.value
            if isinstance(v, bool) or v is None:
                raise ValueError
            if isinstance(v, bytes):
                return v
            if isinstance(v, str):
                return v.encode('utf-8')
            if isinstance(v, int):
                if not 0 <= v <= MAX:
                    raise ValueError
                return v
            raise ValueError
        if isinstance(node, ast.Name):
            return env[node.id]
        if isinstance(node, ast.BinOp):
            left = go(node.left)
            right = go(node.right)
            if isinstance(node.op, ast.Add):
                if not isinstance(left, bytes) or not isinstance(right, bytes):
                    raise ValueError
                return left + right
            if isinstance(node.op, ast.Mult):
                if isinstance(left, bytes) and isinstance(right, int):
                    return left * right
                if isinstance(left, int) and isinstance(right, bytes):
                    return right * left
                raise ValueError
            raise ValueError
        if isinstance(node, ast.Subscript):
            base = go(node.value)
            if not isinstance(base, bytes):
                raise ValueError
            index = node.slice
            if not isinstance(index, ast.Slice) or index.step is not None:
                raise ValueError
            def end(p):
                if p is None:
                    return None
                if not isinstance(p, ast.Constant) or isinstance(p.value, bool) \
                        or not isinstance(p.value, int):
                    raise ValueError
                return p.value
            lo = end(index.lower) or 0
            hi = end(index.upper)
            if hi is None:
                hi = len(base)
            if not 0 <= lo <= hi <= len(base):
                raise ValueError
            return base[lo:hi]
        raise ValueError
    value = go(tree.body)
    if not isinstance(value, bytes):
        raise ValueError
    return value


class Ref:
    def __init__(self, document):
        self.doc = document
        self.seed = document['seed']
        self.env = {}
        for name, source in document['definitions']:
            self.env[name] = evaluate(source, self.env)

    def template(self, value, coordinate):
        assert isinstance(value, str)
        if value.startswith('{{') and value.endswith('}}'):
            return evaluate(value[2:-2].strip(), self.env)
        if '<<random_string>>' not in value:
            return value.encode('utf-8')
        pieces = value.split('<<random_string>>')
        out = []
        for index, piece in enumerate(pieces):
            out.append(piece.encode('utf-8'))
            if index + 1 < len(pieces):
                source = '%s/%s/%d' % (self.seed, coordinate, index)
                out.append(hashlib.sha256(source.encode()).hexdigest()[:20].encode())
        return cat(out)

    # ------------------------------------------------------------- replay #
    def action(self, at, stream, kind, content, end):
        head = at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode()
        if kind in 'Hh':
            body = len(content).to_bytes(8, 'big')
            for name, value in content:
                body += len(name).to_bytes(8, 'big') + name
                body += len(value).to_bytes(8, 'big') + value
        else:
            body = len(content).to_bytes(8, 'big') + content
        return head + body + bytes([1 if end else 0])

    def replay(self):
        doc = self.doc
        timeout = doc['timeout_ms']
        cases = doc['cases']
        states = []
        for index, case in enumerate(cases):
            frames = []
            for position, frame in enumerate(case['frames']):
                kind = frame['Type']
                coordinate = 'case/%d/frame/%d' % (index, position)
                if kind == 'sleep':
                    frames.append(('sleep', frame['Time_to_Stop']))
                elif kind == 'headers':
                    pairs = list(frame['headers_kv'].items()) if 'headers_kv' in frame \
                        else [tuple(pair) for pair in frame['data_to_transfered']]
                    frames.append(('headers',
                                   [(self.template(n, coordinate + '/h/%d/n' % k),
                                     self.template(v, coordinate + '/h/%d/v' % k))
                                    for k, (n, v) in enumerate(pairs)],
                                   frame.get('End_Stream', False)))
                else:
                    frames.append((kind,
                                   self.template(frame['data_to_transfered'],
                                                 coordinate + '/data'),
                                   frame.get('End_Stream', True)))
            states.append({'case': case, 'index': index, 'stream': 4 * index,
                           'frames': frames, 'pc': 0, 'phase': 'init',
                           'closed': False, 'end': False, 'events': [],
                           'sent': b'', 'received': b'', 'body': b'',
                           'frames_count': 0, 'request_frames': 0, 'payload': 0,
                           'state': None, 'at': None})
        events = []
        for record in doc['events']:
            row = dict(record)
            index = len(events)
            if row['kind'] == 'headers':
                row['fields'] = [(self.template(n, 'event/%d/h/%d/n' % (index, k)),
                                  self.template(v, 'event/%d/h/%d/v' % (index, k)))
                                 for k, (n, v) in enumerate(row['fields'])]
            elif row['kind'] == 'data':
                row['data'] = self.template(row['data'], 'event/%d/data' % index)
            events.append(row)
        by_stream = {state['stream']: state for state in states}
        queue = []

        def push(time, kind, order, what):
            queue.append([time, kind, order, what])

        for index in range(len(states)):
            push(0, -1, index, ('start', index))
        for index, row in enumerate(events):
            push(row['at'], 0, index, ('external', index))
        closed = False
        while True:
            if not queue:
                break
            queue.sort(key=lambda row: (row[0], row[1], row[2]))
            when, _, _, what = queue.pop(0)
            now = when
            kind = what[0]
            if kind == 'start' or kind == 'resume':
                state = states[what[1]]
                if state['state'] is not None:
                    continue
                if closed:
                    state['state'] = 'closed'
                    state['at'] = now
                    continue
                state['phase'] = 'send'
                while state['pc'] < len(state['frames']):
                    frame = state['frames'][state['pc']]
                    if frame[0] == 'sleep':
                        state['pc'] += 1
                        push(now + frame[1], 1, state['index'], ('resume', state['index']))
                        state['phase'] = 'paused'
                        break
                    if state['closed']:
                        state['state'] = 'send_error'
                        state['at'] = now
                        break
                    if frame[0] == 'headers':
                        content, end = frame[1], frame[2]
                        state['sent'] += self.action(now, state['stream'], 'H', content, end)
                        state['payload'] += sum(len(n) + len(v) for n, v in content)
                        state['frames_count'] += 1
                        state['request_frames'] += 1
                    elif frame[0] == 'data':
                        content, end = frame[1], frame[2]
                        state['sent'] += self.action(now, state['stream'], 'D', content, end)
                        state['payload'] += len(content)
                        state['frames_count'] += 1
                        state['request_frames'] += 1
                    else:
                        content = frame[1]
                        state['sent'] += self.action(now, state['stream'], 'G', content, False)
                        state['payload'] += len(content)
                        state['frames_count'] += 1
                    if frame[0] != 'datagram' and frame[2]:
                        state['closed'] = True
                    state['pc'] += 1
                else:
                    state['phase'] = 'send_done'
                    if state['end']:
                        state['state'] = 'ok'
                        state['at'] = now
                    else:
                        state['phase'] = 'wait'
                        push(now + timeout, 2, state['index'], ('timeout', state['index']))
                continue
            if kind == 'timeout':
                state = states[what[1]]
                if state['state'] is None and state['phase'] == 'wait' and not state['end']:
                    state['state'] = 'timeout'
                    state['at'] = now
                continue
            row = events[what[1]]
            if row['kind'] == 'close':
                closed = True
                for state in states:
                    if state['state'] is None:
                        state['state'] = 'closed'
                        state['at'] = now
                continue
            state = by_stream.get(row['stream'])
            if state is None or state['state'] is not None or state['end']:
                continue
            content = row['fields'] if row['kind'] == 'headers' else row['data']
            lower = 'h' if row['kind'] == 'headers' else 'd'
            state['received'] += self.action(now, state['stream'], lower, content, row['end'])
            state['events'].append(row)
            if row['kind'] == 'data':
                state['body'] += row['data']
            if row['end']:
                state['end'] = True
                if state['phase'] == 'wait':
                    state['state'] = 'ok'
                    state['at'] = now
        rows = []
        for state in states:
            rows.append({'name': state['case']['name'], 'stream': state['stream'],
                         'state': state['state'], 'at': state['at'],
                         'frames': state['frames_count'],
                         'request_frames': state['request_frames'],
                         'payload_bytes': state['payload'],
                         'sent': fp(state['sent']), 'received': fp(state['received']),
                         'response_frames': len(state['events']),
                         'response_body': fp(state['body']),
                         'origin_count': 0, 'flags': []})
        return rows

    # ------------------------------------------------------------- capture #
    def parse(self, channels):
        out = []
        request_total = 0
        for channel in channels:
            blob = cat([part['data'] for part in channel['parts']])
            runs = []
            position = 0
            for part in channel['parts']:
                length = len(part['data'])
                if not length:
                    continue
                label = part['case']
                if runs and runs[-1][2] == label:
                    runs[-1][1] = position + length
                else:
                    runs.append([position, position + length, label])
                position += length
            requests = []
            error = None
            cursor = 0
            while cursor < len(blob):
                record, cursor, status = self.request(blob, cursor, runs)
                if status != 'ok':
                    error = {'kind': status, 'offset': record}
                    break
                request_total += 1
                requests.append(record)
            committed = []
            index = 0
            consumed = 0
            for part in channel['parts']:
                consumed += len(part['data'])
                while index < len(requests) and requests[index]['end'] <= consumed:
                    index += 1
                committed.append(index)
            out.append({'name': channel['name'], 'bytes': fp(blob),
                        'requests': requests, 'committed': committed, 'error': error})
        return out, request_total

    def line(self, blob, position):
        stop = min(len(blob), position + 8194)
        found = blob.find(b'\n', position, stop)
        if found < 0:
            if len(blob) - position <= 8193:
                return None, position, 'incomplete'
            return None, position, 'syntax'
        if found == position or blob[found - 1] != 13 or found - position - 1 > 8192:
            return None, position, 'syntax'
        return blob[position:found - 1], found + 1, 'ok'

    def fields(self, blob, position, size, count, trailer):
        rows = []
        while True:
            line, position, status = self.line(blob, position)
            if status != 'ok':
                return None, position, status, rows
            size += len(line) + 2
            if size > 65536:
                return None, position, 'syntax', rows
            if not line:
                return position, position, 'ok', rows
            split = line.find(b':')
            if split <= 0:
                return None, position, 'syntax', rows
            name = line[:split]
            if not name or any(c not in b"!#$%&'*+.^_`|~0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-" for c in name):
                return None, position, 'syntax', rows
            value = line[split + 1:]
            if any(not (32 <= c <= 126 or c == 9) for c in value):
                return None, position, 'syntax', rows
            value = value.strip(b' \t')
            if trailer and name.lower() in (b'host', b'content-length', b'transfer-encoding'):
                return None, position, 'syntax', rows
            rows.append((name, value))
            count += 1
            if count > 128:
                return None, position, 'syntax', rows

    def request(self, blob, start, runs):
        line, position, status = self.line(blob, start)
        if status != 'ok':
            return position, position, status
        parts = line.split(b' ')
        if len(parts) != 3:
            return start, start, 'syntax'
        method, target, version = parts
        if not method or any(c not in b"!#$%&'*+.^_`|~0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-" for c in method):
            return start, start, 'syntax'
        if not target or any(not 33 <= c <= 126 for c in target) or version != b'HTTP/1.1':
            return start, start, 'syntax'
        end_of_block, position, status, rows = self.fields(blob, position, len(line) + 2, 1, False)
        if status != 'ok':
            return start, position, status
        position = end_of_block
        headers = rows
        lengths = [v for n, v in headers if n.lower() == b'content-length']
        encodings = [v for n, v in headers if n.lower() == b'transfer-encoding']
        framing = 'none'
        body = b''
        trailers = []
        if encodings:
            if len(encodings) > 1 or lengths or encodings[0].lower() != b'chunked':
                return start, position, 'syntax'
            framing = 'chunked'
            while True:
                line, position, status = self.line(blob, position)
                if status != 'ok':
                    return start, position, status
                split = line.find(b';')
                digits = line if split < 0 else line[:split]
                suffix = None if split < 0 else line[split + 1:]
                if not digits or any(c not in b'0123456789abcdefABCDEF' for c in digits):
                    return start, position, 'syntax'
                if suffix is not None and any(not (32 <= c <= 126 or c == 9) for c in suffix):
                    return start, position, 'syntax'
                trimmed = digits.lstrip(b'0')
                if len(trimmed) > 16:
                    return start, position, 'syntax'
                amount = int(trimmed or b'0', 16)
                if amount > MAX:
                    return start, position, 'syntax'
                if amount == 0:
                    done, position, status, trailers = self.fields(blob, position, 0, 0, True)
                    if status != 'ok':
                        return start, position, status
                    if done is None:
                        return start, position, status
                    position = done
                    break
                if len(blob) - position < amount:
                    return start, position, 'incomplete'
                after = position + amount
                if len(blob) - after < 2:
                    return start, position, 'incomplete'
                if blob[after] != 13 or blob[after + 1] != 10:
                    return start, position, 'syntax'
                body += blob[position:after]
                position = after + 2
        elif lengths:
            total = None
            bad = False
            for value in lengths:
                for member in value.split(b','):
                    digits = member.strip(b' \t')
                    if not digits or any(not 48 <= c <= 57 for c in digits):
                        bad = True
                        break
                    trimmed = digits.lstrip(b'0')
                    if len(trimmed) > 19:
                        bad = True
                        break
                    number = int(trimmed or b'0')
                    if number > MAX:
                        bad = True
                        break
                    if total is None:
                        total = number
                    elif total != number:
                        bad = True
                        break
                if bad:
                    break
            if bad:
                return start, position, 'syntax'
            framing = 'length'
            if len(blob) - position < total:
                return start, position, 'incomplete'
            body = blob[position:position + total]
            position += total
        hosts = [v for n, v in headers if n.lower() == b'host']

        def encode(rows):
            out = len(rows).to_bytes(8, 'big')
            for name, value in rows:
                out += len(name).to_bytes(8, 'big') + name + len(value).to_bytes(8, 'big') + value
            return out

        owners = []
        seen = {}
        order = []
        cursor = start
        while cursor < position:
            for low, high, label in runs:
                if low <= cursor < high:
                    stop = min(high, position)
                    if label not in seen:
                        seen[label] = 0
                        order.append(label)
                    seen[label] += stop - cursor
                    cursor = stop
                    break
            else:
                cursor = position
        owners = [[label, seen[label]] for label in order]
        record = {'start': start, 'end': position, 'method': fp(method),
                  'target': fp(target),
                  'host': fp(hosts[0].lower()) if len(hosts) == 1 else fp(b''),
                  'host_count': len(hosts), 'headers': fp(encode(headers)),
                  'body': fp(body), 'trailers': fp(encode(trailers)),
                  'framing': framing, 'owner': None, 'owners': owners,
                  'flags': [], '_hosts': hosts, '_method': method, '_target': target}
        record['owner'] = record_owners(runs, start)
        return record, position, 'ok'


def record_owners(runs, offset):
    for low, high, label in runs:
        if low <= offset < high:
            return label
    return None


def solve(document):
    ref = Ref(document)
    cases = ref.replay()
    channels, total = ref.parse(document['channels'] if not isinstance(document['channels'], list) or True else [])
    return cases, channels, ref
